script:
import {boot} from './scripts/headless/runner.mjs';
import {advanceGame} from './scripts/headless/advance.mjs';
import {writeFileSync} from 'node:fs';
let game;let result;
try {game=await boot(null,{seed:17});const before=game.minutes();const receipt=await advanceGame(game,{days:45});const saved=await game.save();await game.reload();const reloaded=game.minutes();const encoded=await game.exportFile();await game.importFile(encoded);result={ok:true,fixture:'fresh,seed17',before,receipt,reloaded,imported:game.minutes(),errors:game.errors.map(String),bytes:JSON.stringify(saved).length};}catch(e){result={ok:false,error:String(e?.stack||e)};}finally{game?.close();}writeFileSync(process.env.AUDIT_RESULT,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));if(!result.ok)process.exitCode=1;
